<template>
  <div class="mx-auto max-w-7xl space-y-6 px-4 py-6 sm:px-6 lg:px-8">
    <div class="flex flex-wrap items-end justify-between gap-3"><div><p class="text-xs font-bold uppercase tracking-[.18em] text-orange-600">Customer voice</p><h1 class="mt-1 text-2xl font-bold text-slate-900">Ecommerce feedback</h1><p class="mt-1 text-sm text-slate-500">Review website experience feedback, assign a status, and record the action taken.</p></div><Button label="Refresh" icon="pi pi-refresh" outlined :loading="loading" @click="load" /></div>
    <div class="grid gap-3 md:grid-cols-4"><div v-for="card in summaryCards" :key="card.label" class="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"><p class="text-xs font-semibold uppercase tracking-wider text-slate-500">{{ card.label }}</p><p class="mt-2 text-2xl font-bold" :class="card.color">{{ card.value }}</p></div></div>
    <div class="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"><div class="grid gap-3 md:grid-cols-4"><InputText v-model="filters.search" placeholder="Search comment or email" @keyup.enter="load" /><Select v-model="filters.status" :options="statuses" optionLabel="label" optionValue="value" placeholder="All status" /><Select v-model="filters.topic" :options="topics" optionLabel="label" optionValue="value" placeholder="All topics" /><Button label="Apply filters" icon="pi pi-filter" severity="warn" @click="load" /></div></div>
    <div class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><DataTable :value="items" :loading="loading" responsiveLayout="scroll"><Column header="Feedback" style="min-width:300px"><template #body="{ data }"><p class="line-clamp-2 font-medium text-slate-900">{{ data.message || 'Rating only' }}</p><p class="mt-1 text-xs text-slate-500">{{ data.user ? `${data.user.fname || ''} ${data.user.lname || ''}`.trim() || data.user.email : 'Guest' }} · {{ date(data.created_at) }}</p></template></Column><Column header="Rating"><template #body="{ data }"><span class="text-amber-500"><i v-for="n in 5" :key="n" class="pi mr-0.5" :class="n <= data.rating ? 'pi-star-fill' : 'pi-star'" /></span></template></Column><Column field="topic" header="Topic" /><Column header="Status"><template #body="{ data }"><Tag :value="label(data.status)" :severity="severity(data.status)" /></template></Column><Column header="Action"><template #body="{ data }"><Button label="Review" icon="pi pi-eye" text @click="open(data)" /></template></Column><template #empty><div class="p-10 text-center text-sm text-slate-500">No feedback found.</div></template></DataTable></div>
    <Paginator v-if="total > perPage" :rows="perPage" :totalRecords="total" :first="(page - 1) * perPage" @page="onPage" />
    <Dialog v-model:visible="dialog" modal header="Review customer feedback" class="w-[calc(100%-2rem)] max-w-2xl"><div v-if="active" class="space-y-4"><div class="rounded-xl bg-slate-50 p-4"><p class="text-sm text-slate-600">{{ active.message || 'No written comment.' }}</p><p class="mt-3 text-xs text-slate-500">{{ active.page_url || 'Unknown page' }}</p></div><Select v-model="active.status" :options="statuses.filter(s => s.value)" optionLabel="label" optionValue="value" class="w-full" /><Textarea v-model="active.admin_note" rows="4" class="w-full" placeholder="Internal action note (not visible to customer)" /></div><template #footer><Button label="Close" text @click="dialog = false" /><Button label="Save review" icon="pi pi-check" severity="warn" :loading="saving" @click="save" /></template></Dialog>
  </div>
</template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import axiosClient from '@/axios'; import { useToast } from 'primevue/usetoast'; import DataTable from 'primevue/datatable'; import Column from 'primevue/column'; import InputText from 'primevue/inputtext'; import Select from 'primevue/select'; import Tag from 'primevue/tag'; import Dialog from 'primevue/dialog'; import Textarea from 'primevue/textarea'; import Paginator from 'primevue/paginator'
const toast = useToast(); const loading = ref(false); const saving = ref(false); const items = ref<any[]>([]); const active = ref<any>(null); const dialog = ref(false); const page = ref(1); const perPage = 20; const total = ref(0); const filters = ref({ search: '', status: '', topic: '' }); const statuses = [{ label:'All status',value:'' },{ label:'New',value:'new' },{ label:'In review',value:'in_review' },{ label:'Resolved',value:'resolved' },{ label:'Archived',value:'archived' }]; const topics = [{ label:'All topics',value:'' },{ label:'Website experience',value:'website' },{ label:'Finding products',value:'products' },{ label:'Checkout',value:'checkout' },{ label:'Delivery',value:'delivery' },{ label:'Other',value:'other' }]
const summaryCards = computed(() => [{label:'Total',value:total.value,color:'text-slate-900'},{label:'New',value:items.value.filter(i=>i.status==='new').length,color:'text-orange-600'},{label:'In review',value:items.value.filter(i=>i.status==='in_review').length,color:'text-amber-600'},{label:'Resolved',value:items.value.filter(i=>i.status==='resolved').length,color:'text-emerald-600'}]); const label=(v:string)=>String(v||'').replace('_',' ').replace(/\b\w/g,c=>c.toUpperCase()); const severity=(v:string)=>v==='resolved'?'success':v==='new'?'warn':v==='in_review'?'info':'secondary'; const date=(v:string)=>new Date(v).toLocaleString('en-PH',{dateStyle:'medium',timeStyle:'short'}); function open(row:any){active.value={...row};dialog.value=true} async function load(){loading.value=true;try{const r=await axiosClient.get('/api/admin/ecommerce-feedback',{params:{...filters.value,page:page.value,per_page:perPage}});const p=r.data?.data||{};items.value=p.data||[];total.value=Number(p.total||0)}catch(e:any){toast.add({severity:'error',summary:'Feedback',detail:e?.response?.data?.message||'Unable to load feedback.',life:3000})}finally{loading.value=false}} async function save(){if(!active.value)return;saving.value=true;try{await axiosClient.put(`/api/admin/ecommerce-feedback/${active.value.id}`,{status:active.value.status,admin_note:active.value.admin_note});toast.add({severity:'success',summary:'Saved',detail:'Feedback status updated.',life:2200});dialog.value=false;load()}catch(e:any){toast.add({severity:'error',summary:'Feedback',detail:e?.response?.data?.message||'Unable to save.',life:3000})}finally{saving.value=false}} function onPage(e:any){page.value=e.page+1;load()} onMounted(load)
</script>
